def main() -> None:
    items = []
    seen: dict[str, int] = {}
    for exam, group, exam_name, sign, label, reply, desc in RAW:
        base = safe_filename(label)
        n = seen.get(base, 0)
        seen[base] = n + 1
        article = base if n == 0 else safe_filename(f"{base} ({exam})")
        items.append({
            "exam": exam, "group": group, "examName": exam_name,
            "sign": sign, "label": label, "reply": reply, "desc": desc, "article": article,
        })

    os.makedirs(ART_DIR, exist_ok=True)
    for f in os.listdir(ART_DIR):
        if f.endswith(".md") and f != "index.md":
            os.remove(os.path.join(ART_DIR, f))

    descs: dict[str, dict] = {}
    hints = []
    for it in items:
        open(os.path.join(ART_DIR, it["article"] + ".md"), "w", encoding="utf-8", newline="\n").write(write_article(it))
        key = f"{it['exam']}__{it['sign']}"
        ends = parse_scale_ends(it["desc"]) if it["reply"] == "scale" else None
        body = desc_body(it["desc"]) if it["reply"] == "scale" else it["desc"].strip()
        entry: dict = {"article": it["article"], "body": body, "reply": it["reply"], "label": it["label"]}
        if ends:
            entry["from"] = ends[0]
            entry["to"] = ends[1]
        descs[key] = entry
        h = {"exam": it["exam"], "sign": it["sign"], "label": it["label"], "reply": it["reply"], "article": it["article"], "group": it["group"], "examName": it["examName"]}
        if ends:
            h["from"] = ends[0]
            h["to"] = ends[1]
        hints.append(h)

    payload = {
        "format": "electrodoctor-exam-descs",
        "about": "Тела описаний признаков осмотра (из docs/articles/exams/). Ключ — examId__signId. Собирает tools/exam_articles_export.py / exam_recover_descs.py.",
        "items": descs,
    }
    open(DESCS_JSON, "w", encoding="utf-8", newline="\n").write(json.dumps(payload, ensure_ascii=False, indent=2) + "\n")
    slim = os.path.join(ROOT, "tools", "out", "exam_slim_hints.json")
    os.makedirs(os.path.dirname(slim), exist_ok=True)
    open(slim, "w", encoding="utf-8", newline="\n").write(json.dumps(hints, ensure_ascii=False, indent=2) + "\n")
    print(f"восстановлено {len(items)} → {ART_DIR}")
    print(f"from/to: {sum(1 for v in descs.values() if 'from' in v)}")


if __name__ == "__main__":
    main()
